nta.declaration:
/*
 * Global constants defining the grid and the logical lane width.
 *
 * GRID_W and GRID_H are the visible dimensions of the Frogger map.
 * LANE_W is larger than GRID_W to model the two off-screen cells used by
 * moving objects before they re-enter the visible map.
 */
const int GRID_W = 18;
const int GRID_H = 13;
const int LANE_W = 20;

/*
 * Initial Frogger position.
 * Frogger is respawned here after death, timeout, or successful home bay reach.
 */
const int FROG_SPAWN_X = 9;
const int FROG_SPAWN_Y = 0;

/*
 * Game timing and score bounds.
 * One Uppaal time unit corresponds to 0.1 seconds, hence 30 seconds are modeled
 * as 300 time units and 2 seconds as 20 time units.
 */
const int FROG_MAX_LIVES = 5;
const int MAX_SCORE = 4000;
const int MAX_LEVEL_TIME = 30 * 10;           // 30 seconds * 10 tick/second = 300 tick
const int TIME_DECREMENT_PER_LEVEL = 2 * 10;  // 2 seconds * 10 tick/second = 20 tick
const int RESPAWN_TIME = 19;              // 2 seconds * 10 tick/second = 20 tick
const int MIN_TICK_BETWEEN_FROG_MOVE = 1;

const int RIGHT = 1;
const int LEFT = -1;


/*
 * Diving turtle timing.
 * Stable states are emerged/submerged, while transition states are
 * diving/emerging.
 */
const int DIVING_TURTLE_TRANSITION_STATE_TIMER = 5;
const int DIVING_TURTLE_STABLE_STATE_TIMER = 10;

/*
 * Home bay layout.
 * There are five home bays, each placed every four cells on the home row.
 */
const int HOME_BAYS = 5;
const int HOME_BAY_SPACING = 4;


/*
 * Score increments defined by the game rules.
 */
const int MOVE_UP_SCORE = 1;
const int HOME_BAY_SCORE = 5;
const int LEVEL_COMPLETE_SCORE = 100;

/*
 * Bounded integer types.
 * LaneX ranges over the full logical lane, including off-screen cells.
 * PosY ranges only over visible map rows.
 */
typedef int[0, LANE_W-1] PosX;
typedef int[0, GRID_H-1] PosY;
typedef int[0, FROG_MAX_LIVES] Lives;
typedef int[0, MAX_SCORE] Score;
typedef int [-1,1] Direction;
typedef int[0,7] Cell;

/// ----------------------------------[ Global Variables ]---------------------------------- \\\

/*
 * Frogger state variables.
 * frog_x is a LaneX, so Frogger can also be carried into the two off-screen
 * cells when riding a floating object.
 */
PosX frog_x = FROG_SPAWN_X;
PosY frog_y = FROG_SPAWN_Y;

/*
 * Dynamic game state.
 *
 * diving_turtles_are_submerged exposes the current diving turtle phase to
 * safety checks.
 * home_bay_occupied records which of the five home bays have already been
 * reached.
 */
bool diving_turtles_are_submerged = false;
bool home_bay_occupied[HOME_BAYS] = {false, false, false, false, false};


/// ----------------------------------[ Global Functions ]---------------------------------- \\\

/*
 * Adds points to the current score while saturating at MAX_SCORE.
 *
 * Input:
 *   points - number of points to add.
 *
 * Effect:
 *   Updates score without exceeding MAX_SCORE.
 */
void add_score(int points) {
    score = (score + points > MAX_SCORE) ? MAX_SCORE : score + points;
}




/*
 * Checks whether the home bay corresponding to the x-coordinate given
 * has already been reached and occupied.
 *
 * The home row is organized as five groups of four cells:
 *
 *   H H X X | H H X X | H H X X | H H X X | H H
 *
 * Therefore, each home bay starts every HOME_BAY_SPACING (in this case 4) cells:
 *
 *   bay 0 -> x = 0, 1
 *   bay 1 -> x = 4, 5
 *   bay 2 -> x = 8, 9
 *   bay 3 -> x = 12, 13
 *   bay 4 -> x = 16, 17
 *
 * Since both cells of the same home bay belong to the same block of size
 * HOME_BAY_SPACING, integer division maps them to the correct bay index:
 *
 *   0 / 4 = 0,  1 / 4 = 0
 *   4 / 4 = 1,  5 / 4 = 1
 *   8 / 4 = 2,  9 / 4 = 2
 *   12 / 4 = 3, 13 / 4 = 3
 *   16 / 4 = 4, 17 / 4 = 4
 *
 * Precondition:
 *   This function should only be called after verifying that the given
 *   x-coordinate is an H cell. Wall cells such as x = 2 or x = 3 would also map
 *   to bay 0, but they are not valid home bay cells.
 *
 * Returns:
 *   true if the home bay has already been occupied, false otherwise.
 */
bool is_current_home_bay_occupied() {
    return home_bay_occupied[frog_x / HOME_BAY_SPACING];
}


/*
 * Marks the home bay currently reached by Frogger as occupied.
 *
 * Precondition:
 *   Frogger is currently on a valid H cell.
 */
void set_current_home_bay_as_occupied() {
    home_bay_occupied[frog_x / HOME_BAY_SPACING] = true;
}



bool is_on_last_lane() {
    return frog_y == GRID_H-1;
}


void kill_or_reach_hobe_bay() {
    if ... poi lo faccio
}


/*
 * Clears all occupied home bay flags.
 *
 * Effect:
 *   Used when a new level starts.
 */
void clear_home_bays() {
    int[0,HOME_BAYS]  i;
    for (i = 0; i < HOME_BAYS; i++) {
        home_bay_occupied[i] = false;
    }
}

/*
 * Checks whether all home bays are occupied.
 *
 * Returns:
 *   true if all five home bays have been reached, false otherwise.
 */
bool all_home_bays_occupied() {
    int[0, HOME_BAYS] i;
    for (i = 0; i < HOME_BAYS; i++) {
        if (!home_bay_occupied[i]) return false;
    }
    return true;
}





// Channels
chan vehicle_moving;
chan kill_frog;
chan frog_on_floating;
chan frog_moved;
broadcast chan frog_moved;
broadcast chan submerging;

template.declaration:
// Template Frog
clock tick;                // Frog movements
clock timer;               // Level timer




Lives lives = FROG_MAX_LIVES;
int[0,MAX_LEVEL_TIME] level_time = MAX_LEVEL_TIME;
Score score = 0;


/*
 * Handles Frogger death.
 *
 * Effect:
 *   Decreases lives and respawns Frogger. Score and lane positions are not reset.
 */
void handle_frog_death() {
    lives = lives - 1;
    respawn();
}



/*
 * Repositions Frogger at the spawn cell.
 *
 * Effect:
 *   Does not modify score, lives, lanes, or home bay occupancy.
 */
void respawn() {
    frog_x = FROG_SPAWN_X;
    frog_y = FROG_SPAWN_Y;
}

/*
 * Starts a new level.
 *
 * Effect:
 *   Awards the level completion score, clears all home bays, and reduces the
 *   available level time according to the project rules.
 */
void load_next_level() {
    add_score(LEVEL_COMPLETE_SCORE);
    clear_home_bays();
    level_time = (level_time - TIME_DECREMENT_PER_LEVEL) > 0 ? level_time - TIME_DECREMENT_PER_LEVEL : 0;
}

/*
 * Handles a successful arrival in a free home bay.
 *
 * Effect:
 *   Awards home bay points, marks the bay as occupied, loads the next level if
 *   all bays are occupied, and respawns Frogger.
 */
void reach_home_bay() {
    add_score(HOME_BAY_SCORE);
    set_current_home_bay_as_occupied();
    if (all_home_bays_occupied()) load_next_level();
    respawn();
}


bool can_move(Direction dx, Direction dy)
    // check if frog is trying exit the map
    if (frog_x + dx < 0 || frog_x + dx >= GRID_W || frog_y + dy < 0 || frog_y + dy >= GRID_H) return false;

    // check if frog is trying to move on an unreacheable cell
    Cell next = get_cell(frog_x + dx, frog_y + dy);
    if (next == X || (next == H && is_home_bay_occupied_at(frog_x + dx) )) return false;

    return true;



void move() {
    // update frog position
    frog_x = frog_x + 1;
    add_score(MOVE_UP_SCORE);
}

// Costanti
const Direction direction = (lane_y % 2 == 0) ? RIGHT : LEFT

// Template Vehicle
clock tick;                    // local clock of Vehicle     

int[0,LANE_W-1] shift = 0;


void move_lane() {
    shift = (LANE_W + shift + direction) % LANE_W;
}

bool collision() {
    return lane_structure[(LANE_W + x - shift) % LANE_W];
}

// Template Log
clock x;                    // local clock of Log
int shift = 0;

bool checkKilled(){
    int x_norm = (frog_x - shift) % (GRID_W+2);
    int cell = log_x[x_norm];
    if (cell == 0) return true;
    if (cell == 2 && subemerged) return true;
    return false;
}

void moveLog(){
    if(!checkKilled()){ 
        if(frog_x == GRID_W+1){
            frog_x=0;
        } else {
            frog_x++;
        }
    }
    shift++;
    shift = shift % (GRID_W+2);
}

clock x;

void setSubemerged(bool val){
    subemerged = val;
}

nta.system:
